update local_sources set status='approved', notes='Business''s own website — approved for reading' where domain in ('hsbakery.com','eatatblkswan.com','lochbar.com','harmonybakery.net','bonjourbakerybaltimore.com','roggenart.com','biddlest.com','thebaltimorecateringcompany.com','classactcatering.net','mcfaulsironhorse.com','reserve-restaurant.com','fenwickbakery.com','bakedinbaltimore.com','tastethisbaltimore.com');
update local_sources set status='blocked', notes='Not a single local business website (directory, chain, forum or guide)' where status='pending';
update local_candidates set status='rejected', review_notes=review_notes||' · Not a business site' where status='needs_extraction' and website_domain not in ('hsbakery.com','eatatblkswan.com','lochbar.com','harmonybakery.net','bonjourbakerybaltimore.com','roggenart.com','biddlest.com','thebaltimorecateringcompany.com','classactcatering.net','mcfaulsironhorse.com','reserve-restaurant.com','fenwickbakery.com','bakedinbaltimore.com','tastethisbaltimore.com');
update local_jobs set state='cancelled' where state<>'done' and candidate_id in (select id from local_candidates where status='rejected');
update local_jobs set state='queued', next_attempt_at=now() where state='paused';